draw:
var k = 8.99e9;
var xmin = -0.6, xmax = 0.6;
var left = 30, right = W - 16;
function X(x) { return left + (x - xmin) / (xmax - xmin) * (right - left); }
var x1 = -p.sep / 200, x2 = p.sep / 200;
var q1 = p.q1 * 1e-9, q2 = p.q2 * 1e-9;
function V(x) {
  var r1 = Math.abs(x - x1), r2 = Math.abs(x - x2);
  if (r1 < 0.015) r1 = 0.015;
  if (r2 < 0.015) r2 = 0.015;
  return k * (q1 / r1 + q2 / r2);
}
var axisY = H * 0.20;
var top = H * 0.36, bot = H * 0.94, mid = (top + bot) / 2;
var Vscale = 900;
function Y(v) {
  var y = mid - v / Vscale * (bot - top) / 2;
  if (y < top) y = top;
  if (y > bot) y = bot;
  return y;
}
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// the line the charges sit on
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, axisY); ctx.lineTo(right, axisY); ctx.stroke();

// charges
var cs = [[x1, p.q1], [x2, p.q2]];
for (var i = 0; i < 2; i++) {
  var cx = X(cs[i][0]);
  ctx.fillStyle = cs[i][1] >= 0 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(cx, axisY, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.textAlign = "center";
  ctx.fillText(cs[i][1] >= 0 ? "+" : "-", cx, axisY + 4);
  ctx.fillStyle = C.ink;
  ctx.fillText(cs[i][1].toFixed(1) + " nC", cx, axisY - 14);
}

// zero line and axes
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(left, mid); ctx.lineTo(right, mid); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("V = 0", left + 2, mid - 4);
ctx.fillText("V (volts)", left + 2, top + 12);
ctx.textAlign = "right";
ctx.fillText("x along the line", right, bot + 12);

// the potential curve, drawn in two pieces around each charge
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var started = false;
for (var j = 0; j <= 400; j++) {
  var xx = xmin + (xmax - xmin) * j / 400;
  var near = Math.abs(xx - x1) < 0.016 || Math.abs(xx - x2) < 0.016;
  if (near) { started = false; continue; }
  var px = X(xx), py = Y(V(xx));
  if (!started) { ctx.moveTo(px, py); started = true; } else { ctx.lineTo(px, py); }
}
ctx.stroke();

// probe
var xp = p.probe / 100;
var pxp = X(xp);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(pxp, axisY); ctx.lineTo(pxp, bot); ctx.stroke();
ctx.setLineDash([]);
var vp = V(xp);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(pxp, Y(vp), 4, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("probe", pxp, bot + 12);

var h = 0.002;
var Ex = (V(xp - h) - V(xp + h)) / (2 * h);
out.note = "V = " + vp.toFixed(1) + " V,   E_x = -dV/dx = " + Ex.toFixed(0) + " V/m";
